<?php
namespace App\Services\Face;use App\Contracts\FaceProvider;use Illuminate\Support\Facades\Http;use RuntimeException;
class PythonFaceProvider implements FaceProvider {private function request(){return Http::acceptJson()->timeout(90)->when(config('face.python_token'),fn($r)=>$r->withToken(config('face.python_token')));}private function url(string$p):string{return rtrim(config('face.python_url'),'/').$p;}public function resolveCollection(string$key):string{$r=$this->request()->post($this->url('/collections'),['collection_id'=>$key]);if(!$r->successful())throw new RuntimeException('Local face provider unavailable.');return(string)($r->json('collection_id')??$key);}public function indexFace(string$c,string$e,string$b):array{$r=$this->request()->attach('image',$b,'photo.jpg')->post($this->url('/collections/'.$c.'/faces'),['external_id'=>$e]);if(!$r->successful())throw new RuntimeException('Local face indexing failed.');return['face_id'=>(string)$r->json('face_id'),'confidence'=>(float)$r->json('confidence',100)];}public function search(string$c,string$b,float$t,int$m):array{$r=$this->request()->attach('selfie',$b,'selfie.jpg')->post($this->url('/collections/'.$c.'/search'),['threshold'=>$t,'max_results'=>$m]);if(!$r->successful())throw new RuntimeException('Local face search failed.');return(array)$r->json('matches',[]);}public function removeFaces(string$c,array$ids):void{$this->request()->delete($this->url('/collections/'.$c.'/faces'),['face_ids'=>$ids])->throw();}public function deleteCollection(string$c):void{$this->request()->delete($this->url('/collections/'.$c))->throw();}public function health():array{try{return['healthy'=>$this->request()->get($this->url('/health'))->successful(),'provider'=>'python'];}catch(\Throwable){return['healthy'=>false,'provider'=>'python','error'=>'Provider unavailable.'];}}}
